import random

import pytest


def make_ids(n: int, seed: int) -> list[int]:
    """Return `n` distinct non-negative record ids, determined only by `seed`.

    The same `(n, seed)` always gives the same list, in the same order, on
    every run. The function is pure: it uses a private generator seeded from
    `seed`, so it does not read or change the global `random` state, and it
    does no I/O and reads no clock or environment.

    Raises ValueError if `n` is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    rng = random.Random(seed)
    return rng.sample(range(2**62), n)


def test_length_matches_n() -> None:
    for n in (0, 1, 2, 10, 1000):
        assert len(make_ids(n, 42)) == n


def test_zero_is_empty() -> None:
    assert make_ids(0, 0) == []


def test_ids_are_distinct() -> None:
    ids = make_ids(5000, 7)
    assert len(set(ids)) == len(ids)


def test_ids_are_non_negative_ints() -> None:
    ids = make_ids(200, 3)
    assert all(isinstance(i, int) and i >= 0 for i in ids)


def test_same_seed_same_result() -> None:
    assert make_ids(100, 123) == make_ids(100, 123)


def test_same_seed_same_result_across_other_calls() -> None:
    first = make_ids(50, 9)
    make_ids(30, 10)
    make_ids(70, 11)
    assert make_ids(50, 9) == first


def test_different_seeds_differ() -> None:
    assert make_ids(100, 1) != make_ids(100, 2)


def test_negative_and_large_seeds() -> None:
    for seed in (-1, -(2**40), 0, 2**70):
        ids = make_ids(20, seed)
        assert len(set(ids)) == 20
        assert ids == make_ids(20, seed)


def test_ignores_global_random_state() -> None:
    random.seed(1)
    a = make_ids(25, 5)
    random.seed(999)
    b = make_ids(25, 5)
    assert a == b


def test_does_not_disturb_global_random_state() -> None:
    random.seed(2024)
    before = random.getstate()
    make_ids(25, 5)
    assert random.getstate() == before


def test_negative_n_raises() -> None:
    with pytest.raises(ValueError):
        make_ids(-1, 0)
